Add-Type -AssemblyName System.Drawing
$out=Split-Path -Parent $MyInvocation.MyCommand.Path;$c=Get-Content -Raw -Encoding UTF8 (Join-Path $out 'korean-architecture-content.json')|ConvertFrom-Json
$font=New-Object System.Drawing.Font('Malgun Gothic',12);$small=New-Object System.Drawing.Font('Malgun Gothic',10);$label=New-Object System.Drawing.Font('Malgun Gothic',14,[System.Drawing.FontStyle]::Bold);$title=New-Object System.Drawing.Font('Malgun Gothic',27,[System.Drawing.FontStyle]::Bold);$ink=New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(20,30,45));$white=New-Object System.Drawing.SolidBrush([System.Drawing.Color]::White);$green=New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(232,247,235));$green2=New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(28,112,54),2);$orange=New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(255,243,229));$orange2=New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(222,92,19),2);$blue=New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(235,242,255));$blue2=New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(38,80,190),2);$purple=New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(244,238,255));$purple2=New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(88,43,180),2);$gray=New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(248,250,252));$gray2=New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(90,105,125),2);$line=New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(55,65,81),2)
function Box($g,$x,$y,$w,$h,$head,$body,$fill,$stroke){$g.FillRectangle($fill,$x,$y,$w,$h);$g.DrawRectangle($stroke,$x,$y,$w,$h);$sf=[System.Drawing.StringFormat]::new();$sf.Alignment='Center';$sf.LineAlignment='Near';$g.DrawString($head,$label,$ink,[System.Drawing.RectangleF]::new($x+8,$y+10,$w-16,32),$sf);$g.DrawString($body,$small,$ink,[System.Drawing.RectangleF]::new($x+14,$y+50,$w-28,$h-58),$sf)}
function Arrow($g,$x1,$y1,$x2,$y2,$txt=''){$g.DrawLine($line,$x1,$y1,$x2,$y2);$g.FillPolygon($ink,@([System.Drawing.Point]::new($x2,$y2),[System.Drawing.Point]::new($x2-10,$y2-5),[System.Drawing.Point]::new($x2-10,$y2+5)));if($txt){$sf=[System.Drawing.StringFormat]::new();$sf.Alignment='Center';$g.DrawString($txt,$small,$ink,[System.Drawing.RectangleF]::new(($x1+$x2)/2-70,($y1+$y2)/2-20,140,38),$sf)}}
function Canvas($w,$h){$b=New-Object System.Drawing.Bitmap($w,$h);$g=[System.Drawing.Graphics]::FromImage($b);$g.Clear([System.Drawing.Color]::White);$g.SmoothingMode='AntiAlias';return @($b,$g)}
function Save($b,$g,$name){$g.Dispose();$b.Save((Join-Path $out $name),[System.Drawing.Imaging.ImageFormat]::Png);$b.Dispose()}

# Main: detailed standalone architecture
$p=Canvas 2100 1250;$b=$p[0];$g=$p[1];$g.DrawString('1. Main 아키텍처',$title,$ink,60,25);$g.DrawString('현재 구현된 API 서버의 내부 계층과 요청 처리 순서',$font,$ink,70,75);Box $g 50 250 250 300 $c.user.head $c.user.body $gray $gray2;Box $g 350 250 280 300 $c.frontend.head $c.frontend.body $green $green2;Arrow $g 300 400 350 400 '질문';$g.DrawRectangle($green2,680,130,850,980);$g.DrawString('Main API Server · Node.js HTTP Server',$label,$ink,900,150);Box $g 720 210 770 135 $c.routes.head $c.routes.body $gray $green2;Box $g 720 375 770 145 $c.validation.head $c.validation.body $green $green2;Box $g 720 550 770 170 $c.orchestrator.head $c.orchestrator.body $green $green2;Arrow $g 1105 345 1105 375 '요청';Arrow $g 1105 520 1105 550 '검증';Box $g 720 770 360 210 $c.knowledge.head $c.knowledge.body $blue $blue2;Box $g 1130 770 360 210 $c.data.head $c.data.body $blue $blue2;Arrow $g 900 720 900 770 '조회';Arrow $g 1080 875 1130 875 '읽기';Box $g 720 1010 360 210 $c.agents.head $c.agents.body $orange $orange2;Box $g 1130 1010 360 210 $c.model.head $c.model.body $orange $orange2;Arrow $g 1250 720 1250 1010 '생성';Arrow $g 1080 1110 1130 1110 '호출';Box $g 1600 180 430 230 $c.a2a.head $c.a2a.body $purple $purple2;Box $g 1600 470 430 230 $c.ops.head $c.ops.body $purple $purple2;Box $g 1600 760 430 230 $c.response.head $c.response.body $green $green2;Arrow $g 1530 300 1600 300 '외부';Arrow $g 1530 800 1600 850 '통합';Save $b $g 'main-architecture-ko.png'

# Cat: same comparison-oriented layout as reference image
$p=Canvas 2450 1450;$b=$p[0];$g=$p[1];$g.DrawString('2. Cat / Catalog 아키텍처',$title,$ink,650,25);$g.DrawString('기존 이미지와 동일한 비교용 레이아웃 · Cat 영역만 독립적으로 확대',$font,$ink,820,75);Box $g 30 360 210 430 $c.user.head $c.user.body $gray $gray2;Box $g 275 360 240 430 $c.frontend.head $c.frontend.body $green $green2;Arrow $g 240 560 275 560 '질문';$g.DrawRectangle($green2,550,120,650,1120);$g.DrawString('Cat API · Catalog Q&A Server',$label,$ink,720,145);Box $g 580 205 590 135 $c.validation.head $c.validation.body $green $green2;Box $g 580 365 590 165 'Cat Orchestrator · catalog mode' '카탈로그 질문만 분리 처리`n직접 조회 우선 · 불필요한 모델 호출 최소화`n요청 캐시 · mode 라우팅 · 응답 메트릭' $green $green2;Box $g 580 560 590 180 $c.knowledge.head $c.knowledge.body $blue $blue2;Box $g 580 770 590 180 $c.agents.head 'catalog Agent 중심`n콘텐츠 목록 · 분류 · 메타데이터 해석`n필요 시 codex · lore와 연결' $orange $orange2;Box $g 580 980 590 180 $c.model.head '구조화 데이터로 답할 수 없을 때만 호출`nMock · OpenAI 호환 · LangChain adapter`n근거 evidence를 포함해 답변 생성' $orange $orange2;Arrow $g 875 340 875 365 '검증';Arrow $g 875 530 875 560 '지식 조회';Arrow $g 875 740 875 770 'Agent';Arrow $g 875 950 875 980 'Model';Box $g 1280 170 430 260 'Catalog Knowledge Layer' 'knowledge.json`nsources.json`nsourceRef · 출처 링크`n카탈로그 항목 · 키워드 · 답변`nlocale 및 story 데이터' $blue $blue2;Box $g 1280 500 430 260 'Specialized Agents' 'catalog`n필요 시 codex · lore`n질문 의도 분석`n콘텐츠 설명 및 관계 해석' $orange $orange2;Box $g 1280 830 430 260 'Model Adapter' '답변 초안 및 근거 기반 생성`n구조화 데이터 조회 실패 시 사용`n일관된 생성 인터페이스' $orange $orange2;Arrow $g 1200 650 1280 300 '지식 검색';Arrow $g 1200 850 1280 630 '전문 Agent';Arrow $g 1200 1050 1280 960 '생성';Box $g 1780 170 570 300 $c.a2a.head $c.a2a.body $purple $purple2;Box $g 1780 550 570 300 $c.ops.head $c.ops.body $purple $purple2;Box $g 1780 930 570 250 $c.response.head $c.response.body $green $green2;Arrow $g 1710 300 1780 300 '필요 시 외부';Arrow $g 1710 680 1780 680 '상태·출처';Arrow $g 1710 1010 1780 1050 '응답 통합';$g.DrawRectangle($blue2,30,1230,2320,150);$g.DrawString('Cat 처리 흐름',$label,$ink,70,1255);$g.DrawString('질문 입력  →  catalog mode 확인  →  knowledge.json 검색  →  sourceRef 연결  →  답변 + 출처 반환',$font,$ink,330,1260);Save $b $g 'cat-architecture-ko.png'

# Integration: Main connected to four services
$p=Canvas 2350 1350;$b=$p[0];$g=$p[1];$g.DrawString('3. Main + Cat + Video + Development + WorkMate',$title,$ink,330,25);$g.DrawString('Main이 공통 요청 계약으로 각 서비스에 분배하고 결과를 통합하는 전체 구성',$font,$ink,760,75);Box $g 40 450 240 300 $c.user.head $c.user.body $gray $gray2;Box $g 350 350 400 500 $c.orchestrator.head 'API Gateway · Orchestrator`n공통 인증 · 요청 검증`nmode 기반 분배`nrequestId · context 전달`n결과 통합 및 응답 반환' $green $green2;Arrow $g 280 600 350 600 '공통 요청';Box $g 850 150 400 220 $c.cat.head $c.cat.body $blue $blue2;Box $g 850 420 400 220 $c.video.head $c.video.body $gray $gray2;Box $g 850 690 400 220 $c.development.head $c.development.body $gray $gray2;Box $g 850 960 400 220 $c.workmate.head $c.workmate.body $gray $gray2;Arrow $g 750 470 850 260 'catalog';Arrow $g 750 560 850 530 'video';Arrow $g 750 650 850 800 'dev-guide';Arrow $g 750 740 850 1070 'workContext';Box $g 1370 150 390 220 $c.data.head $c.data.body $blue $blue2;Box $g 1370 420 390 220 $c.response.head $c.response.body $green $green2;Box $g 1370 690 390 220 $c.model.head $c.model.body $orange $orange2;Box $g 1370 960 390 220 $c.a2a.head $c.a2a.body $purple $purple2;Arrow $g 1250 260 1370 260 '조회';Arrow $g 1250 530 1370 530 '결과';Arrow $g 1250 800 1370 800 '생성';Arrow $g 1250 1070 1370 1070 '연동';Box $g 1850 410 440 380 $c.ops.head $c.ops.body $purple $purple2;Arrow $g 1760 530 1850 530 'health · metrics · sources';$g.DrawRectangle($blue2,40,1190,2250,100);$g.DrawString('통합 원칙',$label,$ink,75,1220);$g.DrawString('requestId · mode · context · evidence를 공통 계약으로 유지하고 Main에서 서비스별 결과를 하나의 응답으로 통합',$font,$ink,300,1225);Save $b $g 'main-connected-services-ko.png';Write-Output 'Created three separate Korean architecture PNG files.'
